/*
 * FETROS — Umm al-Qura month table (js/data/umm-alqura.js)
 *
 * Month lengths for the Umm al-Qura Hijri calendar, years 1402–1500 AH.
 * Each character is one month, in order from Muharram 1402: "1" = 30 days, "0" = 29 days.
 * The table was taken from the Umm al-Qura month data bundled in the moment-hijri package
 * (MIT licence, github.com/xsoh/moment-hijri), and checked day by day against it.
 * It follows the published Umm al-Qura calculations (Umm al-Qura University, Makkah).
 * Outside this range the app falls back to the tabular (arithmetic) Hijri calendar.
 *
 * Exposes: window.FETROS.Data.ummAlQura (read-only).
 */
(function (global) {
  'use strict';

  var NS = global.FETROS = global.FETROS || {};
  NS.Data = NS.Data || {};

  NS.Data.ummAlQura = Object.freeze({
    firstYear: 1402,
    lastYear: 1500,
    // Julian Day Number of 1 Muharram 1402 AH (1981-10-28 in the Gregorian calendar).
    anchorJdn: 2444906,
    monthBits: ''
  });
})(typeof window !== 'undefined' ? window : globalThis);
